295	function promoteAgent(orgModule, experienceModule, agentId) {
296	  const record = orgModule.findAgent(agentId);
297	  if (!record) return { ok: false, error: 'Agent not found' };
298	  if (record.status === 'retired') return { ok: false, error: 'Cannot promote a retired agent' };
299	
300	  const currentLevel = record.level ?? 0;
301	  if (currentLevel >= 8) return { ok: false, error: 'Already at max level (Fellow)' };
302	
303	  const nextThreshold = experienceModule.LEVEL_THRESHOLDS[currentLevel + 1];
304	  if (!nextThreshold) return { ok: false, error: 'No higher level available' };
305	
306	  // Grant a promotion bonus: enough XP to cross the threshold
307	  const bonusYears = Math.max(0, nextThreshold.minYoE - (record.yearsOfExperience || 0)) + 0.1;
308	
309	  const updated = orgModule.upsertAgent(agentId, {
310	    level: currentLevel + 1,
311	    levelTitle: nextThreshold.title,
312	    levelColor: nextThreshold.color,
313	    canMentor: nextThreshold.canMentor,
314	    canShipProd: nextThreshold.canShipProd,
315	    yearsOfExperience: Math.round(((record.yearsOfExperience || 0) + bonusYears) * 10) / 10,
316	    lastPromoted: new Date().toISOString(),
317	    lastReview: new Date().toISOString(),
318	    status: record.status === 'probation' ? 'active' : record.status,
319	  });
320	
321	  logWitnessEvent({
322	    agent: agentId,
323	    classification: 'PROMOTION',
324	    meta: { fromLevel: currentLevel, toLevel: currentLevel + 1, toTitle: nextThreshold.title },
325	  });
326	
327	  return { ok: true, agent: updated };
328	}
