642	    '',
643	    `**Promotions:** ${promotions.length}`,
644	    ...promotions.map((p) => `- ${p.agent} → ${p.to}`),
645	    '',
646	    `**PIPs opened:** ${pipsOpened.length}`,
647	    ...pipsOpened.map((p) => `- ${p.agent}`),
648	    '',
649	    `**Recommendations pending:**`,
650	    `- Promotion candidates: ${(recommendations.promotionCandidates || []).length}`,
651	    `- PIP candidates: ${(recommendations.pipCandidates || []).length}`,
652	  ].join('\n');
