1	/**
2	 * Experience Module — computes per-agent experience level, years of
3	 * experience, and skill vectors from multiple signals:
4	 *
5	 *   1. Training depth   → word count of the agent's .md file
6	 *   2. Tenure           → days since hiredAt
7	 *   3. Runs             → count from agent-runs.json
8	 *   4. Successes        → success_rate * run count
9	 *   5. Patterns         → patterns/good/*.md files where this agent is cited
10	 *   6. Antipatterns     → lessons/bugs.jsonl entries where agent_that_shipped matches
11	 *
12	 * The formula is deterministic, transparent, and tunable via
13	 * ~/.claude/org/experience-weights.json (optional override).
14	 *
15	 * YoE (years of experience) is scaled to feel human:
16	 *   ~10 KB of training content = 1 year
17	 *   ~20 runs = 1 year
18	 *   ~90 days of tenure = 1 year
19	 *
20	 * Levels map to human career titles from Trainee (0) to Distinguished (8).
21	 */
22	
23	const fs = require('fs');
24	const path = require('path');
25	const os = require('os');
26	
27	const HOME = os.homedir();
28	const CLAUDE_DIR = path.join(HOME, '.claude');
29	const AGENTS_DIR = path.join(CLAUDE_DIR, 'agents');
30	const MEMORY_DIR = path.join(CLAUDE_DIR, 'memory');
31	const WEIGHTS_PATH = path.join(CLAUDE_DIR, 'org', 'experience-weights.json');
32	
33	// Path to Polyglot's run-tracking files (caller-controlled in tests)
34	const POLYGLOT_ROOT = path.resolve(__dirname, '..');
35	const AGENT_RUNS_PATH = path.join(POLYGLOT_ROOT, 'agent-runs.json');
36	
37	// ──────────────────────────────────────────────────────────────────────────
38	//  Weights — tunable via ~/.claude/org/experience-weights.json
39	// ──────────────────────────────────────────────────────────────────────────
40	
41	const DEFAULT_WEIGHTS = {
42	  trainingKbPerYear: 10,   // 10 KB of .md content = 1 YoE
43	  runsPerYear: 20,         // 20 runs = 1 YoE
44	  daysPerYear: 90,         // 90 days tenure = 1 YoE
45	  patternWeight: 0.5,      // each pattern contributed = +0.5 YoE
46	  antipatternPenalty: 0.3, // each antipattern triggered = -0.3 YoE
47	  successBonus: 0.5,       // high success rate bonus (max +0.5 YoE)
48	};
